CREATE TABLE IF NOT EXISTS student_exit_campus_releases (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',student_exit_id INTEGER NOT NULL,release_mode TEXT NOT NULL CHECK(release_mode IN ('collected','independent')),permission_evidence_type TEXT NOT NULL,permission_reference TEXT NOT NULL,collector_name TEXT,collector_relationship TEXT,approved_collector_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(approved_collector_confirmed IN (0,1)),identity_verified INTEGER NOT NULL DEFAULT 0 CHECK(identity_verified IN (0,1)),identity_verification_method TEXT,independent_release_permitted INTEGER NOT NULL DEFAULT 0 CHECK(independent_release_permitted IN (0,1)),authorised_by TEXT NOT NULL,authorised_at TEXT NOT NULL DEFAULT(datetime('now')),released_by TEXT,released_at TEXT,receiving_adult_name TEXT,destination TEXT,transport_method TEXT,expected_return_at TEXT,closed_by TEXT,closed_at TEXT,closure_outcome TEXT,UNIQUE(app_id,student_exit_id),FOREIGN KEY(student_exit_id) REFERENCES student_exits(id));
CREATE TABLE IF NOT EXISTS student_exit_custody_events (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',student_exit_id INTEGER NOT NULL,event_type TEXT NOT NULL CHECK(event_type IN ('authorised','released','closed','corrected')),actor_id TEXT NOT NULL,evidence_json TEXT NOT NULL,confirmed_by_human INTEGER NOT NULL CHECK(confirmed_by_human=1),occurred_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(student_exit_id) REFERENCES student_exits(id));
CREATE INDEX IF NOT EXISTS idx_student_exit_custody_history ON student_exit_custody_events(app_id,student_exit_id,occurred_at);
